// ---------- кнопка «?» и всплывающее пояснение ----------
window.helpBtn = (key) => (window.HELP[key]
  ? `<button type="button" class="help" data-help="${key}" aria-label="Пояснение: ${window.HELP[key].title}">?</button>`
  : '');

/** Подсказка при наведении для кнопок (короткий текст). */
window.helpTitle = (key) => {
  const h = window.HELP[key];
  return h ? ` title="${(h.short || h.title).replace(/"/g, '&quot;')}"` : '';
};

(function setupPopover() {
  const pop = document.createElement('div');
  pop.className = 'popover';
  pop.hidden = true;
  pop.setAttribute('role', 'dialog');
  document.body.append(pop);
  let anchor = null;

  const esc = (s) => String(s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

  function close() {
    pop.hidden = true;
    anchor = null;
  }

  function open(btn) {
    const h = window.HELP[btn.dataset.help];
    if (!h) return;
    if (anchor === btn) return close();
    anchor = btn;
    pop.innerHTML = `<div class="pt">${esc(h.title)}</div>${esc(h.text).split('\n').map((p) => (p ? `<div>${p}</div>` : '<div class="gap"></div>')).join('')}`;
    pop.hidden = false;
    const r = btn.getBoundingClientRect();
    const w = Math.min(360, window.innerWidth - 24);
    pop.style.width = `${w}px`;
    let left = Math.min(Math.max(12, r.left + r.width / 2 - w / 2), window.innerWidth - w - 12);
    let top = r.bottom + 8;
    pop.style.left = `${left}px`;
    pop.style.top = `${top}px`;
    const ph = pop.getBoundingClientRect().height;
    if (top + ph > window.innerHeight - 8 && r.top - ph - 8 > 8) pop.style.top = `${r.top - ph - 8}px`;
  }

  document.addEventListener('click', (e) => {
    const btn = e.target.closest('.help');
    if (btn) {
      e.preventDefault();
      e.stopPropagation();
      open(btn);
    } else if (!e.target.closest('.popover')) {
      close();
    }
  }, true);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') close(); });
  window.addEventListener('scroll', close, true);
  window.addEventListener('resize', close);
})();
